struct RotateScript {
    speed: f32,
}

impl Script for RotateScript {
    fn on_start(&mut self) {
        println!("旋转脚本启动");
    }

    fn on_update(&mut self, dt: f32) {
        // 每帧绕Y轴旋转
        self.entity.rotate_y(self.speed * dt);
    }
}

// 使用：
let script = RotateScript { speed: 90.0 }; // 每秒90度
cube.add_script(script);

