struct BounceScript;

impl Script for BounceScript {
    fn on_collision(&mut self, other: &Entity) {
        println!("碰撞到: {}", other.name);

        // 反弹
        let velocity = self.entity.get_velocity();
        self.entity.set_velocity(-velocity);
    }
}
